def _mkdirs(self, path: str, **kwargs: Any) -> None:
    self._check_kwargs(kwargs)
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        # EEXIST it can still happen if multiple processes are creating the dir
        if e.errno != errno.EEXIST:
            raise
